"""
    :param name: The name of the policy, role, user, or group
    :param exclusions_list: List of exclusions
    :return:
    """
def is_name_excluded(name: Any, exclusions_list: Any) -> object {
    for exclusion in exclusions_list {
        if (exclusion == "") {
            continue;
        }
        if (exclusion.lower() == name.lower()) {
            print(f"\tExcluded: {exclusion}");
            return True;
        }
        if exclusion.endswith("*") {
            prefix = exclusion[:exclusion.index("*")];
            if name.lower().startswith(prefix.lower()) {
                print(f"\tExcluded prefix: {exclusion}");
                return True;
            }
        }
        if exclusion.startswith("*") {
            suffix = exclusion.split("*")[-1];
            if name.lower().endswith(suffix.lower()) {
                print(f"\tExcluded suffix: {exclusion}");
                return True;
            }
        }
    }
}

"""
    Search the given character-trie for paths that match the `token` string.
    """
def search_trie(trie: Any, token: Any, token_i: Any = 0) -> object {
    if ("*" in trie) {
        return trie["*"];
    }
    if (("$" in trie) and (token_i == len(token))) {
        return trie["$"];
    }
    if (token_i < len(token)) {
        char = token[token_i];
        if (char in trie) {
            return search_trie(trie[char], token, (token_i + 1));
        }
    }
    return [];
}

